// ===============================
// ORDENAR FILAS
// ===============================
const rows = items
  .map(i => i.json)
  .sort((a, b) => (a.row_number || 0) - (b.row_number || 0));

// Tema para la portada
const temaPortada = $('Obtener campos del formulario').first().json.inf_tema;

const seccionesMap = {};
const ordenAparicion = [];

let currentSection = null;
let currentSubtopic = null;

// ===============================
// CONSTRUIR SECCIONES
// ===============================
for (const row of rows) {
  const seccion = (row.seccion || "").trim();
  const subseccion = (row.subseccion || "").trim();
  const texto = row.texto || "";

  // --- Nueva sección ---
  if (seccion) {
    if (!seccionesMap[seccion]) {
      seccionesMap[seccion] = {
        nombre: seccion,
        subtemas: []
      };
      ordenAparicion.push(seccion);
    }
    currentSection = seccionesMap[seccion];
    currentSubtopic = null;
  }

  // --- Nueva subsección ---
  if (subseccion) {
    if (!currentSection) continue;

    currentSubtopic = { nombre: subseccion };

    if (currentSection.nombre.toLowerCase() === "portada") {
      currentSubtopic.titulo = texto;
    } else {
      currentSubtopic.contenido = [texto];
    }

    currentSection.subtemas.push(currentSubtopic);
    continue;
  }

  // --- Slides adicionales ---
  if (!seccion && !subseccion && currentSubtopic) {
    if (
      currentSection.nombre.toLowerCase() !== "portada" &&
      currentSection.nombre.toLowerCase() !== "trivia"
    ) {
      currentSubtopic.contenido.push(texto);
    }
  }
}

// ===============================
// POSTPROCESO PORTADA
// ===============================
if (seccionesMap["Portada"]) {
  const portada = seccionesMap["Portada"];
  const sub = portada.subtemas[0];

  if (sub) {
    delete sub.contenido;
    sub.titulo = temaPortada;
  }

  portada.prompt = `Genera una imagen en formato PNG, no texto, solo imagen, sobre el tema ${temaPortada}. No incluyas ninguna descripción, solo devuelve la imagen.`;
}

// ===============================
// POSTPROCESO TRIVIA
// ===============================
if (seccionesMap["Trivia"]) {
  const trivia = seccionesMap["Trivia"];
  const sub = trivia.subtemas[0];
  if (sub) {
    delete sub.contenido;
    delete sub.titulo;
  }
}

// ===============================
// ORDEN FINAL FORZADO
// ===============================
const output = [];

// 1. Portada
if (seccionesMap["Portada"]) {
  output.push({ json: seccionesMap["Portada"] });
}

// 2. Contenidos normales
for (const nombre of ordenAparicion) {
  if (
    nombre !== "Portada" &&
    nombre !== "Trivia" &&
    nombre !== "Bibliografía y más información" &&
    nombre !== "Créditos"
  ) {
    output.push({ json: seccionesMap[nombre] });
  }
}

// 3. Trivia
if (seccionesMap["Trivia"]) {
  output.push({ json: seccionesMap["Trivia"] });
}

// 4. Bibliografía
if (seccionesMap["Bibliografía y más información"]) {
  output.push({ json: seccionesMap["Bibliografía y más información"] });
}

// 5. Créditos
if (seccionesMap["Créditos"]) {
  output.push({ json: seccionesMap["Créditos"] });
}

return output;

const tri_id = $json.tri_id;
const trivia = $json.trivia;

const items = trivia.map(q => {
  return {
    json: {
      tri_id: tri_id,
      pregunta: `<p>${q.pregunta}</p>`,
      respuestas: q.respuestas,
      justificacion: q.justificacion
    }
  };
});

return items;

let texto = "";

// =======================================
// Obtener información del formulario
// =======================================
const formulario = $items("Obtener campos del formulario")[0].json;

// Parsear inf_parametros (viene como string JSON)
let parametros = {};
if (formulario.inf_parametros) {
    try {
        parametros = JSON.parse(formulario.inf_parametros);
    } catch (e) {
        parametros = {};
    }
}

// Construir encabezado
texto += `Título: ${parametros.tema || "Sin tema"}\n\n`;
texto += `Estilo de la infografía: ${parametros.estilo || "No especificado"}\n\n`;
texto += `Público objetivo: ${parametros.audiencia || "No especificado"}\n\n`;
texto += `Estilo gráfico: ${parametros.estilo_grafico || "No especificado"}\n\n`;

texto += `\n=======================================\n`;
texto += `        CONTENIDO DE LA INFOGRAFÍA      \n`;
texto += `=======================================\n\n`;

// =======================================
// Temas del nodo (omitiendo portada)
// =======================================
let itemsTemas = $items("Transformar a la estructura original1");

// Omitir primer item (portada)
itemsTemas = itemsTemas.slice(1);

itemsTemas.forEach(item => {
    const tema = item.json;

    texto += `\n\n=== Tema: ${tema.nombre} ===\n\n`;

    if (tema.subtemas) {
        tema.subtemas.forEach(sub => {
            texto += `Subtema: ${sub.nombre}\n\n`;

            if (sub.titulo) {
                texto += `${sub.titulo}\n\n`;
            }

            if (Array.isArray(sub.contenido)) {
                sub.contenido.forEach(parrafo => {
                    texto += parrafo + "\n\n";
                });
            }
        });
    }
});

// =======================================
// Preguntas y respuestas
// =======================================
const itemsPreguntas = $items("Dividir preguntas y respuestas");

texto += `\n\n=======================================\n`;
texto += `           PREGUNTAS Y RESPUESTAS       \n`;
texto += `=======================================\n`;

itemsPreguntas.forEach((item, index) => {
    const p = item.json;

    const preguntaLimpia = p.pregunta
        .replace(/<\/?p>/g, "")
        .trim();

    texto += `\nPregunta ${index + 1}: ${preguntaLimpia}\n\n`;
    texto += `Opciones:\n`;

    let respuestaCorrecta = "";

    p.respuestas.forEach((r, i) => {
        texto += `${i + 1}. ${r.texto}\n`;
        if (r.correcta) respuestaCorrecta = r.texto;
    });

    texto += `\nRespuesta correcta: ${respuestaCorrecta}\n\n`;
});

// =======================================
// Crear el segundo texto sin trivia
// =======================================
let texto2 = "";

// Solo el título del tema
texto2 += `Título: ${parametros.tema || "Sin tema"}\n\n`;

// Agregar contenido de temas (sin símbolos especiales, solo texto)
itemsTemas.forEach(item => {
    const tema = item.json;

    // Agregar nombre del tema (sin símbolos "===")
    texto2 += `Tema: ${tema.nombre}\n\n`;

    if (tema.subtemas) {
        tema.subtemas.forEach(sub => {
            // Agregar nombre del subtema (sin la palabra "Subtema:")
            texto2 += `${sub.nombre}\n\n`;

            if (sub.titulo) {
                texto2 += `${sub.titulo}\n\n`;
            }

            if (Array.isArray(sub.contenido)) {
                sub.contenido.forEach(parrafo => {
                    texto2 += parrafo + "\n\n";
                });
            }
        });
    }
});

// =======================================
// Devolver los dos textos con nombres diferentes para n8n
// =======================================
return [
    {
        json: {
            texto_completo: texto.trim(),
            texto_contenido: texto2.trim()
        }
    }
];

// Tomamos el string desde el item de entrada
const raw = $input.item.json;

// Si el JSON viene en una propiedad concreta (ej: "data")
const jsonString =
    typeof raw === 'string'
        ? raw
        : Object.values(raw)[0];

// Parseamos
const parsed = JSON.parse(jsonString);

// Devolvemos como item válido de n8n
return [
    {
        json: parsed
    }
];

// Obtener los datos del nodo anterior (slides)
const slides = $input.all();
const result = [];

// Valores por defecto
let estiloGrafico = "Ilustración digital semirealista, líneas definidas, sombreado suave, estilo limpio y profesional";
let audiencia = "estudiantes universitarios";

// =======================================
// Obtener información del formulario
// =======================================
try {
  const formulario = $items("Obtener campos del formulario")[0].json;

  let parametros = {};
  if (formulario.inf_parametros) {
    try {
      parametros = JSON.parse(formulario.inf_parametros);

      if (parametros.estilo_grafico) {
        const estiloMap = {
          "realista": "Ilustración digital semirealista, líneas definidas, sombreado suave, estilo limpio y profesional",
          "académico": "Estilo académico, ilustrativo, claro y educativo",
          "minimalista": "Estilo minimalista, líneas simples, colores planos",
          "cartoon": "Estilo cartoon, colores vibrantes, líneas expresivas",
          "técnico": "Estilo técnico, diagramas claros, precisión en detalles",
          "academico": "Estilo académico, ilustrativo, claro y educativo",
          "tecnico": "Estilo técnico, diagramas claros, precisión en detalles"
        };

        const estiloKey = parametros.estilo_grafico.toLowerCase();
        estiloGrafico =
          estiloMap[estiloKey] ||
          `Estilo gráfico: ${parametros.estilo_grafico}`;
      }

      if (parametros.audiencia) {
        audiencia = parametros.audiencia;
      }

    } catch (e) {
      console.error("Error al parsear inf_parametros:", e);
    }
  }
} catch (error) {
  console.log("No se encontró el nodo 'Obtener campos del formulario', usando valores por defecto");
}

// Encontrar el título de la portada (plantilla 8)
let tituloPortada = "";
const portada = slides.find(item => item.json.sld_plantilla === 8);
if (portada) {
  tituloPortada = portada.json.sld_titulo || "";
}

// Contador para los elementos que sí procesamos
let filteredIndex = 0;

// Procesar todos los slides
slides.forEach((slide, originalIndex) => {
  const slideData = slide.json;

  if (slideData.sld_plantilla === 2 || slideData.sld_plantilla === 8) {
    const textoLimpio = slideData.sld_texto1 ?
      slideData.sld_texto1.replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim() :
      '';

    const textoCorto = textoLimpio;

    let promptText = `Genera una imagen semirealista de alto detalle con estilo limpio, profesional y sin textura granulada. La imagen debe tener líneas definidas, sombreado suave. El estilo visual debe ser claro, detallado y ligeramente estilizado, evitando el hiperrealismo. Ten en cuenta los siguientes parámetros para que ilustres la siguiente información:

• Tema general: ${tituloPortada || "Tema principal"}
• Subtema: ${slideData.sld_titulo || "Subtema"}
• Estilo gráfico deseado: ${estiloGrafico}
• Audiencia objetivo: ${audiencia}
• Texto base que la imagen debe explicar o describir: "${textoCorto}"

Instrucciones adicionales:
La imagen debe representar visualmente el subtema indicado, reflejando el estilo del texto y el estilo gráfico requeridos.
Debe ser clara, comprensible y adecuada para la audiencia especificada.
Debe incorporar elementos visuales que traduzcan de manera efectiva el contenido del texto base.
Evitar ambigüedad y mantener coherencia estética en la composición.

La imagen generada debe cumplir una función didáctica explícita: representar procesos, relaciones, estructuras o comparaciones. No se permiten imágenes meramente estéticas o metafóricas sin valor explicativo. La idea del texto es que sea un complemento explicativo para el contexto. 

No añadas textos extensos en la imagen ni títulos, si hay textos en la imagen deben ser en español.

RESTRICCIONES CRÍTICAS:
- La imagen generada debe tener fondo blanco con el fin de ser editable con mayor facilidad
- El texto debe poder entenderse SIN la imagen
- La imagen debe ayudar a comprender mejor el texto
- No usar metáforas visuales ambiguas
- No incluir instrucciones de animación
`;


    // ================================
    //  🚀 CONFIG CORRECTA PARA GEMINI 3
    // ================================
    const openrouterPayload = {
      model: "google/gemini-3-pro-image-preview",

      // MUY IMPORTANTE PARA QUE GENERE IMAGEN
      max_output_tokens: 4096,
      // fallback si OpenRouter lo convierte internamente
      max_tokens: 4096,

      modalities: ["image", "text"], // obligamos imagen

      image_config: {
        aspect_ratio: "16:9"
      },

      messages: [
        {
          role: "user",
          content: [
            {
              type: "text",
              text: promptText
            }
          ]
        }
      ]
    };

    // Metadata
    const metadata = {
      prompt_index: filteredIndex,
      original_index: originalIndex,
      sld_nombre: slideData.sld_nombre || "",
      sld_titulo: slideData.sld_titulo || "",
      sld_id: slideData.sld_id || "",
      sld_plantilla: slideData.sld_plantilla || 0,
      sld_id_subseccion: slideData.sld_id_subseccion || "",
      original_prompt: promptText,
      estilo_grafico: estiloGrafico,
      audiencia: audiencia,
      titulo_portada: tituloPortada,
      texto_base: textoCorto
    };

    result.push({
      json: {
        openrouter: openrouterPayload,
        metadata: metadata
      },
      pairedItem: {
        item: originalIndex
      }
    });

    filteredIndex++;
  }
});

return result;

const temaGeneral = $('Obtener campos del formulario1').first().json.inf_nombre;

return items.map(item => {
  const tema = item.json.tema;
  const subtema = item.json.subtema;
  const textoBase = item.json.texto;

  const prompt = `
ROL:
Guionista académico e instruccional senior, enfocado en diseño instruccional,
no en redacción de contenido base.

OBJETIVO:
Diseñar la estructura instruccional de UN slide interactivo con botones y pop-ups,
manteniendo el contenido base EXACTAMENTE como fue entregado.

CONTEXTO:
- Tema general del recurso: ${temaGeneral}
- Sección: ${tema}
- Sub-sección (tema específico del slide): ${subtema}

CONTENIDO BASE (USO OBLIGATORIO):
El siguiente texto debe:
- Copiarse literalmente
- Mantenerse intacto
- NO ser resumido
- NO ser reescrito
- NO ser parafraseado

TEXTO:
"""
${textoBase}
"""

INSTRUCCIONES CLAVE:
1. El campo "contenido_principal" debe contener EXACTAMENTE el texto anterior.
2. La IA SOLO debe:
   - Diseñar el diseño instruccional
   - Proponer botones y pop-ups
   - Sugerir animaciones
   - Definir referentes visuales
3. Los pop-ups NO deben repetir el contenido base, sino ampliarlo o profundizarlo conceptualmente.
4. Cada pop-up debe ser una unidad conceptual autónoma.
5. Definir entre 2 y 4 botones como máximo.

REFERENTES VISUALES (OBLIGATORIO):
- Tipo: Imagen o Video
- Fuentes permitidas:
  * Wikimedia Commons
  * NASA, ESA
  * Universidades y organismos científicos
  * Canales educativos verificados
- Prohibido:
  * Sitios comerciales
  * Marketing
  * Recursos con copyright frágil
- Incluir SIEMPRE:
  * Consulta de búsqueda exacta
  * Enlace base (repositorio o canal)
  * Qué observar visualmente
  * Qué NO copiar literalmente

FORMATO DE SALIDA (OBLIGATORIO):
- Responder ÚNICAMENTE en JSON válido
- NO incluir texto fuera del JSON
- Respetar EXACTAMENTE esta estructura:

{
  "tema_general": "${temaGeneral}",
  "seccion": "${tema}",
  "subseccion": "${subtema}",
  "slide": {
    "contenido_principal": "${textoBase}",
    "diseno_instruccional": {
      "numero_botones": 0,
      "instruccion_usuario": ""
    },
    "botones": [
      {
        "id": 1,
        "titulo": "",
        "popup": {
          "titulo": "",
          "texto_completo": "",
          "animacion_sugerida": ""
        }
      }
    ],
    "referentes_visuales": [
      {
        "para_boton_id": 1,
        "tipo": "Imagen | Video",
        "fuente_confiable": "",
        "consulta_busqueda_sugerida": "",
        "enlace_base": "",
        "que_observar": "",
        "que_no_copiar": ""
      }
    ],
    "nota_editorial_diseno": ""
  }
}

REGLA DE VALIDACIÓN:
Si el texto en "contenido_principal" no coincide exactamente con el texto base,
la respuesta es inválida.
`;

  return {
    json: {
      prompt
    }
  };
});

// Tomamos explícitamente los items del nodo "Extraer textos slides"
const items = $items("Extraer textos slides");
const datos = items.map(i => i.json);

const prompt = `
Genera una trivia de 25 preguntas (Deben ser exactamente 25 preguntas distribuidas de la siguiente forma: exactamente 10 de nivel básico, exactamente 10 de nivel intermedio y exactamente 5 de nivel avanzado) en formato JSON usando la siguiente información de subtemas y contenidos:

${JSON.stringify(datos, null, 2)}

Reglas IMPORTANTES:
- Cada pregunta debe tener exactamente 4 opciones de respuesta.
- Solo UNA de las opciones puede ser válida (correcta = true).
- Aunque el texto contenga varias posibles respuestas correctas, debes escoger únicamente una como la válida.
- Las demás opciones deben ser distractores: incorrectas pero coherentes y plausibles dentro del tema.
- Los distractores NO deben ser también correctos según el texto original.
- Debes mantener una ortografía impecable y respetar con exactitud los términos utilizados en la información (NO abreviar, NO modificar términos, NO escribirlos incorrectamente).
- Debes ser preciso y fiel a los datos proporcionados. No puedes inventar información que no esté explícitamente en el contenido.
- Todas las preguntas deben poder responderse SOLO con el contenido del recurso.
- Prohibido introducir conceptos externos.
- Evitar memorización superficial.
- Escalonar dificultad real.
- Las respuestas correctas deben estar distribuidas entre A, B, C y D (no todas en la misma posición).

Reglas adicionales:
- Además de las respuestas, cada pregunta debe incluir un campo "justificacion".
- La justificación debe explicar por qué la respuesta correcta es correcta exclusivamente usando la información proporcionada.
- La justificación debe sonar natural, directa y explicativa.
- NO debe mencionar frases como:
  "según el texto", "según el contenido", "de acuerdo a la información proporcionada", ni ninguna referencia meta al origen de la información.
- El formato de salida debe ser estrictamente un JSON como este:

[
  {
    "pregunta": "texto de la pregunta",
    "respuestas": [
      { "texto": "opción 1", "correcta": false },
      { "texto": "opción 2", "correcta": true },
      { "texto": "opción 3", "correcta": false },
      { "texto": "opción 4", "correcta": false }
    ],
    "justificacion": "explicación clara y natural de por qué la respuesta correcta lo es, usando únicamente la información proporcionada",
    "dificultad": "básico"
  }
]
`;

return [
  {
    chatInput: prompt
  }
];

const resultado = [];

for (const item of items) {
  const tema = item.json.nombre;

  if (!item.json.subtemas) continue;

  for (const subtemaObj of item.json.subtemas) {
    const subtema = subtemaObj.nombre;
    const contenidos = subtemaObj.contenido;

    if (!Array.isArray(contenidos)) continue;

    for (const texto of contenidos) {
      if (typeof texto === 'string' && texto.trim() !== '') {
        resultado.push({
          json: {
            tema,
            subtema,
            texto
          }
        });
      }
    }
  }
}

return resultado;

// Tomamos explícitamente los items del nodo "Extraer textos slides"
const items = $items("Extraer textos slides");

// Extraemos solo el campo "texto" y los concatenamos
const textoConcatenado = items
  .map(item => item.json.texto)
  .join("\n\n"); // doble salto para separar párrafos

return [
  {
    json: {
      texto_concatenado: textoConcatenado
    }
  }
];

// Tomamos el string desde el item de entrada
const raw = $input.item.json;

// Si el JSON viene en una propiedad concreta (ej: "data")
const jsonString =
    typeof raw === 'string'
        ? raw
        : Object.values(raw)[0];

// Parseamos
const parsed = JSON.parse(jsonString);

// Devolvemos como item válido de n8n
return [
    {
        json: parsed
    }
];

const temaGeneral = $('Obtener campos del formulario1').first().json.inf_nombre;

return items.map((item, index) => {
  let raw = item.json.output;

  // 🧹 Limpiar markdown si viene envuelto en ```json
  if (typeof raw === 'string') {
    raw = raw
      .replace(/```json\s*/i, '')
      .replace(/```$/, '')
      .trim();
  }

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (error) {
    throw new Error(`Item ${index}: la salida de la IA no es JSON válido`);
  }

  // Forzar tema general
  parsed.tema_general = temaGeneral;

  // Validaciones mínimas
  if (!parsed.slide) {
    throw new Error(`Item ${index}: falta el objeto slide`);
  }

  if (!parsed.slide.contenido_principal) {
    throw new Error(`Item ${index}: falta contenido_principal`);
  }

  if (!parsed.slide.botones || !Array.isArray(parsed.slide.botones)) {
    throw new Error(`Item ${index}: botones inválidos o inexistentes`);
  }

  if (!parsed.slide.referentes_visuales) {
    throw new Error(`Item ${index}: faltan referentes_visuales`);
  }

  return {
    json: parsed
  };
});

const salida = [];

for (const item of items) {
  if (!item.json.output) continue;

  // Parseamos el string JSON
  const parsed = JSON.parse(item.json.output);

  // Accedemos al array de preguntas
  const trivia = parsed.trivia || [];

  for (const pregunta of trivia) {
    salida.push({
      json: pregunta
    });
  }
}

return salida;

// ===============================
// ORDENAR FILAS
// ===============================
const rows = items
  .map(i => i.json)
  .sort((a, b) => (a.row_number || 0) - (b.row_number || 0));

// Tema para la portada
const temaPortada = $('Obtener campos del formulario').first().json.inf_tema;

const seccionesMap = {};
const ordenAparicion = [];

let currentSection = null;
let currentSubtopic = null;

// ===============================
// CONSTRUIR SECCIONES
// ===============================
for (const row of rows) {
  const seccion = (row.seccion || "").trim();
  const subseccion = (row.subseccion || "").trim();
  const texto = row.texto || "";

  // --- Nueva sección ---
  if (seccion) {
    if (!seccionesMap[seccion]) {
      seccionesMap[seccion] = {
        nombre: seccion,
        subtemas: []
      };
      ordenAparicion.push(seccion);
    }
    currentSection = seccionesMap[seccion];
    currentSubtopic = null;
  }

  // --- Nueva subsección ---
  if (subseccion) {
    if (!currentSection) continue;

    currentSubtopic = { nombre: subseccion };

    if (currentSection.nombre.toLowerCase() === "portada") {
      currentSubtopic.titulo = texto;
    } else {
      currentSubtopic.contenido = [texto];
    }

    currentSection.subtemas.push(currentSubtopic);
    continue;
  }

  // --- Slides adicionales ---
  if (!seccion && !subseccion && currentSubtopic) {
    if (
